839	  private void bindAWSClient(URI name, boolean dtEnabled) throws IOException {
840	    Configuration conf = getConf();
841	    credentials = null;
842	    String uaSuffix = "";
843	
844	    if (dtEnabled) {
845	      // Delegation support.
846	      // Create and start the DT integration.
847	      // Then look for an existing DT for this bucket, switch to authenticating
848	      // with it if so.
849	
850	      LOG.debug("Using delegation tokens");
851	      S3ADelegationTokens tokens = new S3ADelegationTokens();
852	      this.delegationTokens = Optional.of(tokens);
853	      tokens.bindToFileSystem(getCanonicalUri(),
854	          createStoreContext(),
855	          createDelegationOperations());
856	      tokens.init(conf);
857	      tokens.start();
858	      // switch to the DT provider and bypass all other configured
859	      // providers.
860	      if (tokens.isBoundToDT()) {
861	        // A DT was retrieved.
862	        LOG.debug("Using existing delegation token");
863	        // and use the encryption settings from that client, whatever they were
864	      } else {
865	        LOG.debug("No delegation token for this instance");
866	      }
867	      // Get new credential chain
868	      credentials = tokens.getCredentialProviders();
869	      // and any encryption secrets which came from a DT
870	      tokens.getEncryptionSecrets()
871	          .ifPresent(this::setEncryptionSecrets);
872	      // and update the UA field with any diagnostics provided by
873	      // the DT binding.
874	      uaSuffix = tokens.getUserAgentField();
875	    } else {
876	      // DT support is disabled, so create the normal credential chain
877	      credentials = createAWSCredentialProviderSet(name, conf);
878	    }
879	    LOG.debug("Using credential provider {}", credentials);
880	    Class<? extends S3ClientFactory> s3ClientFactoryClass = conf.getClass(
881	        S3_CLIENT_FACTORY_IMPL, DEFAULT_S3_CLIENT_FACTORY_IMPL,
882	        S3ClientFactory.class);
883	
884	    String endpoint = accessPoint == null
885	        ? conf.getTrimmed(ENDPOINT, DEFAULT_ENDPOINT)
886	        : accessPoint.getEndpoint();
887	
888	    S3ClientFactory.S3ClientCreationParameters parameters = null;
889	    parameters = new S3ClientFactory.S3ClientCreationParameters()
